@staticmethod
def _fully_transparent_index(image):
    # Index of the first palette entry with alpha 0, or None.
    if image.mode != "P":
        return None
    palette = image.getpalette("RGBA")
    if not palette:
        return None
    for index in range(len(palette) // 4):
        if palette[index * 4 + 3] == 0:
            return index
    return None

def avif_enabled(self):
    return HAVE_AVIF

